```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Document",
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "Unique identifier for the document"
    },
    "title": {
      "type": "string",
      "description": "Title of the document"
    },
    "content": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/Block"
      },
      "description": "Array of content blocks"
    },
    "metadata": {
      "type": "object",
      "properties": {
        "author": {
          "type": "string"
        },
        "created_at": {
          "type": "string",
          "format": "date-time"
        },
        "updated_at": {
          "type": "string",
          "format": "date-time"
        }
      }
    }
  },
  "required": ["id", "content"],
  "definitions": {
    "Block": {
      "oneOf": [
        {
          "$ref": "#/definitions/Paragraph"
        },
        {
          "$ref": "#/definitions/Image"
        },
        {
          "$ref": "#/definitions/Heading"
        }
      ]
    },
    "Paragraph": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": ["paragraph"],
          "const": "paragraph"
        },
        "text": {
          "type": "string"
        }
      },
      "required": ["type", "text"]
    },
    "Image": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": ["image"],
          "const": "image"
        },
        "src": {
          "type": "string",
          "format": "uri"
        },
        "alt": {
          "type": "string"
        }
      },
      "required": ["type", "src"]
    },
    "Heading": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": ["heading"],
          "const": "heading"
        },
        "level": {
          "type": "integer",
          "minimum": 1,
          "maximum": 6
        },
        "text": {
          "type": "string"
        }
      },
      "required": ["type", "level", "text"]
    }
  }
}
```
